PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS auth_users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, bannedUntil TEXT, rawMetadata TEXT);
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY, expiresAt TEXT NOT NULL, token TEXT NOT NULL UNIQUE, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS auth_sessions_user ON auth_sessions(userId);
CREATE TABLE IF NOT EXISTS auth_accounts (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt TEXT, refreshTokenExpiresAt TEXT, scope TEXT, password TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS auth_account_provider ON auth_accounts(providerId,accountId);
CREATE TABLE IF NOT EXISTS auth_verifications (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_verifications_identifier ON auth_verifications(identifier);
CREATE TABLE IF NOT EXISTS auth_rate_limits (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS "catalogues" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"product_type" TEXT NOT NULL,"model_slug" TEXT,"stripe_price_id" TEXT,"status" TEXT NOT NULL DEFAULT 'draft',"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CHECK (product_type IN ('model_catalogue','magazine_edition','physical_shop')),CHECK (status IN ('draft','published')),CHECK ((product_type='model_catalogue' AND model_slug IS NOT NULL) OR product_type IN ('magazine_edition','physical_shop')));
CREATE TABLE IF NOT EXISTS "memberships" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"user_id" TEXT NOT NULL,"provider" TEXT NOT NULL,"tier" TEXT NOT NULL,"status" TEXT NOT NULL,"provider_subscription_id" TEXT NOT NULL,"provider_reference_id" TEXT,"current_period_end" TEXT,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"stripe_customer_id" TEXT,"billing_interval" TEXT,FOREIGN KEY("user_id") REFERENCES "auth_users"("id") ON DELETE CASCADE,CHECK (provider IN ('stripe','verotel')),CHECK (tier IN ('standard','impura')),CHECK (status IN ('active','canceled','expired','refunded','chargeback')),CHECK (billing_interval IS NULL OR billing_interval IN ('monthly','yearly')));
CREATE TABLE IF NOT EXISTS "member_media" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"title" TEXT NOT NULL,"alt_text" TEXT NOT NULL,"bucket" TEXT NOT NULL DEFAULT 'member-media',"storage_path" TEXT NOT NULL,"min_tier" TEXT NOT NULL,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"stripe_price_id" TEXT,"model_slug" TEXT,"catalogue_id" TEXT,"position" INTEGER NOT NULL DEFAULT 0,FOREIGN KEY("catalogue_id") REFERENCES "catalogues"("id") ON DELETE CASCADE,CHECK (bucket IN ('member-media','member-media-r2')),CHECK (min_tier IN ('standard','impura')));
CREATE TABLE IF NOT EXISTS "portfolio_purchases" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"user_id" TEXT NOT NULL,"media_id" TEXT,"stripe_checkout_session_id" TEXT NOT NULL,"stripe_payment_intent_id" TEXT,"status" TEXT NOT NULL,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"catalogue_id" TEXT,FOREIGN KEY("user_id") REFERENCES "auth_users"("id") ON DELETE CASCADE,FOREIGN KEY("media_id") REFERENCES "member_media"("id") ON DELETE CASCADE,FOREIGN KEY("catalogue_id") REFERENCES "catalogues"("id") ON DELETE CASCADE,CHECK (status IN ('paid','refunded','disputed')),CHECK ((media_id IS NOT NULL)+(catalogue_id IS NOT NULL)=1));
CREATE TABLE IF NOT EXISTS "shop_products" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"stripe_price_id" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CHECK (status IN ('draft','published','coming_soon')));
CREATE TABLE IF NOT EXISTS "shop_product_images" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"shop_product_id" TEXT NOT NULL,"storage_path" TEXT NOT NULL,"alt_text" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY("shop_product_id") REFERENCES "shop_products"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "shop_orders" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"user_id" TEXT NOT NULL,"shop_product_id" TEXT NOT NULL,"stripe_checkout_session_id" TEXT NOT NULL,"stripe_payment_intent_id" TEXT,"customer_email" TEXT,"shipping_details" TEXT,"status" TEXT NOT NULL,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY("user_id") REFERENCES "auth_users"("id") ON DELETE CASCADE,FOREIGN KEY("shop_product_id") REFERENCES "shop_products"("id") ON DELETE RESTRICT,CHECK (status IN ('paid','refunded','disputed')));
CREATE TABLE IF NOT EXISTS "editorial_stories" ("slug" TEXT PRIMARY KEY NOT NULL,"title" TEXT NOT NULL,"location" TEXT NOT NULL DEFAULT '',"model" TEXT NOT NULL DEFAULT '',"deck" TEXT NOT NULL DEFAULT '',"body" TEXT NOT NULL DEFAULT '[]',"photographer" TEXT NOT NULL DEFAULT '',"release_date" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'draft',"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CHECK (status IN ('draft','published')),CHECK (slug<>'' AND slug NOT GLOB '*[^a-z0-9-]*' AND substr(slug,1,1)<>'-' AND substr(slug,-1)<>'-' AND instr(slug,'--')=0));
CREATE TABLE IF NOT EXISTS "editorial_images" ("id" TEXT PRIMARY KEY NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-8'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),"editorial_slug" TEXT NOT NULL,"storage_path" TEXT,"public_url" TEXT,"alt_text" TEXT NOT NULL DEFAULT '',"position" INTEGER NOT NULL DEFAULT 0,"published" INTEGER NOT NULL DEFAULT 0,"created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY("editorial_slug") REFERENCES "editorial_stories"("slug") ON DELETE CASCADE,CHECK ((storage_path IS NOT NULL)+(public_url IS NOT NULL)=1),CHECK (published IN (0,1)));
CREATE TABLE IF NOT EXISTS "stripe_events" ("event_id" TEXT PRIMARY KEY NOT NULL,"event_type" TEXT NOT NULL,"received_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS "verotel_events" ("event_key" TEXT PRIMARY KEY NOT NULL,"event_type" TEXT NOT NULL,"provider_subscription_id" TEXT NOT NULL,"received_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),"payload" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS catalogue_price ON catalogues(stripe_price_id);
CREATE UNIQUE INDEX IF NOT EXISTS membership_subscription ON memberships(provider_subscription_id);
CREATE UNIQUE INDEX IF NOT EXISTS membership_reference ON memberships(provider_reference_id);
CREATE UNIQUE INDEX IF NOT EXISTS media_path ON member_media(storage_path);
CREATE UNIQUE INDEX IF NOT EXISTS portfolio_media ON portfolio_purchases(user_id,media_id);
CREATE UNIQUE INDEX IF NOT EXISTS portfolio_catalogue ON portfolio_purchases(user_id,catalogue_id);
CREATE UNIQUE INDEX IF NOT EXISTS portfolio_session ON portfolio_purchases(stripe_checkout_session_id);
CREATE UNIQUE INDEX IF NOT EXISTS shop_price ON shop_products(stripe_price_id);
CREATE UNIQUE INDEX IF NOT EXISTS shop_image_path ON shop_product_images(storage_path);
CREATE UNIQUE INDEX IF NOT EXISTS order_session ON shop_orders(stripe_checkout_session_id);
CREATE UNIQUE INDEX IF NOT EXISTS editorial_image_path ON editorial_images(storage_path);
ALTER TABLE stripe_events ADD COLUMN processing_token TEXT;
ALTER TABLE verotel_events ADD COLUMN processing_token TEXT;
CREATE INDEX IF NOT EXISTS member_media_catalogue ON member_media(catalogue_id);
CREATE INDEX IF NOT EXISTS editorial_images_story ON editorial_images(editorial_slug,position);
